def choose_move(observation):
    def clamp(v):
        return -1 if v < -1 else (1 if v > 1 else v)

    def is_num(v):
        return isinstance(v, (int, float))

    def to_pos(v):
        if isinstance(v, dict):
            if is_num(v.get("x")) and is_num(v.get("y")):
                return [int(v.get("x")), int(v.get("y"))]
            if is_num(v.get("row")) and is_num(v.get("col")):
                return [int(v.get("col")), int(v.get("row"))]
        if isinstance(v, (list, tuple)) and len(v) >= 2 and is_num(v[0]) and is_num(v[1]):
            return [int(v[0]), int(v[1])]
        return None

    def get_self_pos(obs):
        keys = ["self", "agent", "player", "me", "pos", "position", "location"]
        for k in keys:
            p = to_pos(obs.get(k))
            if p is not None:
                return p
        for k in ["self_pos", "agent_pos", "player_pos", "my_pos"]:
            p = to_pos(obs.get(k))
            if p is not None:
                return p
        return [0, 0]

    def collect_positions(val):
        out = []
        if val is None:
            return out
        if isinstance(val, dict):
            for v in val.values():
                p = to_pos(v)
                if p is not None:
                    out.append(p)
                elif isinstance(v, (list, tuple)):
                    for e in v:
                        p2 = to_pos(e)
                        if p2 is not None:
                            out.append(p2)
        elif isinstance(val, (list, tuple)):
            for v in val:
                p = to_pos(v)
                if p is not None:
                    out.append(p)
                elif isinstance(v, dict):
                    p = to_pos(v.get("pos", v.get("position", v.get("location"))))
                    if p is not None:
                        out.append(p)
        return out

    def nearest(points, pos):
        best = None
        bd = None
        for p in points:
            d = abs(p[0] - pos[0]) + abs(p[1] - pos[1])
            if bd is None or d < bd:
                bd = d
                best = p
        return best, bd

    def get_grid(obs):
        for k in ["grid", "map", "world", "board"]:
            g = obs.get(k)
            if isinstance(g, (list, tuple)) and g:
                return g
        return None

    me = get_self_pos(observation)
    grid = get_grid(observation)

    resources = []
    for k in ["resources", "resource", "food", "items", "pellets", "targets", "objective", "goals"]:
        resources.extend(collect_positions(observation.get(k)))

    enemies = []
    for k in ["enemies", "enemy", "opponents", "opponent", "others", "threats", "hazards"]:
        enemies.extend(collect_positions(observation.get(k)))

    allies = []
    for k in ["allies", "teammates", "friends"]:
        allies.extend(collect_positions(observation.get(k)))

    # Territory-specific hints: prefer unowned / neutral cells if a grid encodes ownership.
    territory_targets = []
    if grid is not None:
        h = len(grid)
        w = len(grid[0]) if h and isinstance(grid[0], (list, tuple)) else 0
        if h and w:
            # Scan a sparse set of cells to find likely neutral/unclaimed spaces.
            step_y = max(1, h // 12)
            step_x = max(1, w // 12)
            for y in range(0, h, step_y):
                row = grid[y]
                if not isinstance(row, (list, tuple)):
                    continue
                for x in range(0, min(len(row), w), step_x):
                    cell = row[x]
                    good = False
                    if isinstance(cell, dict):
                        owner = cell.get("owner", cell.get("team"))
                        if owner is None or owner == -1 or owner == "neutral":
                            good = True
                    elif isinstance(cell, int):
                        if cell == 0 or cell == -1:
                            good = True
                    elif cell is None:
                        good = True
                    if good:
                        territory_targets.append([x, y])

    # Threat model: avoid nearby enemies more than chase far ones.
    threat_dx = 0
    threat_dy = 0
    threat_w = 0
    for e in enemies:
        dx = me[0] - e[0]
        dy = me[1] - e[1]
        dist = abs(dx) + abs(dy)
        if dist == 0:
            dist = 1
        w = 1.0 / dist
        threat_dx += (1 if dx > 0 else -1 if dx < 0 else 0) * w
        threat_dy += (1 if dy > 0 else -1 if dy < 0 else 0) * w
        threat_w += w

    # Target bias: resources first, then territory.
    target = None
    td = None
    if resources:
        target, td = nearest(resources, me)
    elif territory_targets:
        target, td = nearest(territory_targets, me)
    elif allies and enemies:
        # Pursuit-evasion: move toward nearest enemy only if no immediate threat dominance.
        target, td = nearest(enemies, me)

    # Candidate moves
    moves = []
    for dx in (-1, 0, 1):
        for dy in (-1, 0, 1):
            moves.append([dx, dy])

    def cell_blocked(x, y):
        if grid is None:
            return False
        h = len(grid)
        if y < 0 or y >= h:
            return True
        row = grid[y]
        if not isinstance(row, (list, tuple)):
            return False
        if x < 0 or x >= len(row):
            return True
        cell = row[x]
        if isinstance(cell, dict):
            for kk in ["wall", "blocked", "obstacle"]:
                if cell.get(kk):
                    return True
            return False
        return cell in ("#", "X", "x", 1)

    def score_move(m):
        nx = me[0] + m[0]
        ny = me[1] + m[1]
        s = 0.0

        if m[0] == 0 and m[1] == 0:
            s -= 0.05

        if cell_blocked(nx, ny):
            return -9999.0

        # Prefer staying away from enemies.
        if enemies:
            for e in enemies:
                d = abs(nx - e[0]) + abs(ny - e[1])
                s += 1.5 * d
                if d == 0:
                    s -= 50.0
                elif d == 1:
                    s -= 6.0

        # Go toward main target.
        if target is not None:
            d0 = abs(me[0] - target[0]) + abs(me[1] - target[1])
            d1 = abs(nx - target[0]) + abs(ny - target[1])
            s += (d0 - d1) * 4.0

        # Territorial exploration: favor open cells / center-ish movement when no target.
        if target is None and grid is not None:
            # Simple openness estimate in 4-neighborhood.
            open_n = 0
            for ox, oy in ((1,0),(-1,0),(0,1),(0,-1)):
                if not cell_blocked(nx + ox, ny + oy):
                    open_n += 1
            s += open_n * 0.2

        # Mild inertia to reduce jitter.
        prev_dx = observation.get("last_move", [0, 0])
        if isinstance(prev_dx, (list, tuple)) and len(prev_dx) >= 2:
            if m[0] == prev_dx[0] and m[1] == prev_dx[1]:
                s += 0.15

        # If surrounded by threats, choose move that maximizes distance from threat vector.
        if threat_w > 0:
            s += (m[0] * threat_dx + m[1] * threat_dy) * 1.2

        return s

    best = [0, 0]
    best_s = None
    for m in moves:
        sc = score_move(m)
        if best_s is None or sc > best_s:
            best_s = sc
            best = m

    return [clamp(best[0]), clamp(best[1])]

